#!/usr/bin/env node
// Vendors MapLibre GL JS (UMD build with inline worker + CSS) into the app so the
// map page never loads it from a CDN at runtime. Re-run to bump the version:
//   node app/scripts/vendor-maplibre.mjs [version]
// Writes app/src/components/map/vendor/maplibreGl.ts (generated, do not edit).
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const version = process.argv[2] ?? '5.24.0';
const tmp = mkdtempSync(join(tmpdir(), 'maplibre-'));
const out = JSON.parse(execFileSync('npm', ['pack', `maplibre-gl@${version}`, '--json', '--pack-destination', tmp], { encoding: 'utf8' }))[0];
const expected = execFileSync('npm', ['view', `maplibre-gl@${version}`, 'dist.integrity'], { encoding: 'utf8' }).trim();
if (out.integrity !== expected) throw new Error(`integrity mismatch: ${out.integrity} != ${expected}`);
execFileSync('tar', ['-xzf', join(tmp, out.filename), '-C', tmp]);
const dist = join(tmp, 'package', 'dist');
const js = readFileSync(join(dist, 'maplibre-gl.js'), 'utf8');
const css = readFileSync(join(dist, 'maplibre-gl.css'), 'utf8');
const license = readFileSync(join(tmp, 'package', 'LICENSE.txt'), 'utf8');

// Inlined into a <script>/<style>; make sure nothing can close the tag early.
const safe = (s, tag) => s.replace(new RegExp(`</${tag}`, 'gi'), `<\\/${tag}`);
const body = `// GENERATED by app/scripts/vendor-maplibre.mjs from maplibre-gl@${version} (${out.integrity}). Do not edit.
/*
${license.replace(/\*\//g, '* /')}
*/
export const MAPLIBRE_VERSION = ${JSON.stringify(version)};
export const maplibreCss = ${JSON.stringify(safe(css, 'style'))};
export const maplibreJs = ${JSON.stringify(safe(js, 'script'))};
`;
const target = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'components', 'map', 'vendor', 'maplibreGl.ts');
writeFileSync(target, body);
console.log(`wrote ${target} (${(body.length / 1024).toFixed(0)} KB)`);
